<template>
	<view class="messages-page tab-page">
		<view class="messages-shell" :style="{ paddingTop: topPadding + 'px' }">
			<view class="hero-row" :style="{ height: heroHeight + 'px' }">
				<view class="title-group">
					<view class="subtitle-wrap">
						<text class="page-subtitle">把心事，说给同频的人</text>
						<view class="subtitle-mark" />
					</view>
				</view>
			</view>

			<view class="recent-head">
				<text class="recent-title">最近聊天</text>
				<view class="recent-actions">
					<text @click="markAllRead">全部已读</text>
					<view class="sort-icon"><view /><view /><view /></view>
				</view>
			</view>

			<scroll-view class="recent-scroll" scroll-y enhanced :show-scrollbar="false" refresher-enabled :refresher-triggered="refreshing" @refresherrefresh="refreshConversations" @scroll="handleListScroll">
				<view v-if="messageAd.enabled" class="message-ad-wrap">
					<view
						class="message-ad-banner"
						hover-class="message-ad-banner-hover"
						hover-stay-time="80"
						@click="goMembership"
					>
						<view class="message-ad-accent" />
						<view class="message-ad-icon">
							<image src="/static/img/vip.png" mode="aspectFit" />
						</view>
						<view class="message-ad-content">
							<view class="message-ad-meta">
								<text class="message-ad-kicker">轻享会员</text>
								<text class="message-ad-label">推广</text>
							</view>
							<text class="message-ad-title">{{ messageAd.primaryText }}</text>
							<text class="message-ad-subtitle">无限畅聊 · 专属标识 · 更多权益</text>
						</view>
						<view class="message-ad-action">
							<text>›</text>
						</view>
						<text class="message-ad-spark message-ad-spark-one">✦</text>
						<text class="message-ad-spark message-ad-spark-two">✦</text>
					</view>
				</view>
				<view class="chat-list">
					<view v-if="!loading && !conversations.length" class="empty-chat-state">
						<text>还没有私信会话</text>
						<text>从广场或用户主页发起一次聊天吧</text>
					</view>
					<view v-for="item in conversations" :key="item.id" class="chat-swipe">
						<movable-area class="chat-swipe-area">
							<movable-view
								class="chat-swipe-track"
								direction="horizontal"
								:x="item.swipeX"
								:out-of-bounds="false"
								:animation="true"
								:damping="36"
								:friction="2"
								@touchstart="handleSwipeStart(item.id)"
								@change="handleSwipeChange($event, item.id)"
								@touchend="handleSwipeEnd(item.id)"
								@touchcancel="handleSwipeEnd(item.id)"
							>
								<view class="chat-row" @click="handleConversationClick(item.id)">
									<view class="avatar-wrap">
										<image class="avatar" :src="item.avatar" mode="aspectFill" />
										<view v-if="item.online" class="online-dot" />
									</view>
									<view class="chat-main">
										<view class="chat-top">
											<view class="name-line">
												<VipName class="chat-name" :name="item.name" :is-member="item.isMember" />
												<text v-if="item.match" class="match-chip">同频</text>
											</view>
											<text class="chat-time">{{ item.time }}</text>
										</view>
										<view class="chat-bottom">
											<text class="chat-preview">{{ item.preview }}</text>
											<text v-if="item.unread" class="chat-badge">{{ item.unread }}</text>
											<view v-else-if="item.dot" class="tiny-dot" />
										</view>
									</view>
								</view>
								<view class="chat-delete-action" @click.stop="confirmDeleteConversation(item)">删除</view>
							</movable-view>
						</movable-area>
					</view>
				</view>
			</scroll-view>
		</view>
	</view>
</template>

<script>
import { DEFAULT_AVATAR_URL } from '../../config';
import { deleteConversation, fetchConversations, markConversationRead } from '../../api/message';
import { isChatUserOnline, sendChatSocketEvent, subscribeChatEvents } from '../../utils/chatSocket';
import { showRequestError } from '../../utils/feedback';
import { getAppBootstrapConfig, loadAppMode } from '../../utils/appMode';
import { setMessageTabBadge } from '../../utils/messageTabBadge';
import * as profileGuard from '../../utils/profileGuard';
import VipName from '../../components/VipName.vue';

export default {
	components: { VipName },
	data() {
		return {
			topPadding: 44,
			heroHeight: 32,
			loading: false,
			refreshing: false,
			deletingConversationId: '',
			swipedConversationId: '',
			swipeGestureId: '',
			swipeGestureStartX: 0,
			swipeActionWidthPx: 60,
			swipeLatestPositions: {},
			suppressRowClickUntil: 0,
			realtimeUnsubscribe: null,
			messageAd: {
				enabled: false,
				primaryText: '把喜欢的对话，再多聊一会'
			},
			conversations: []
		};
	},
	onLoad() {
		this.setTopPadding();
	},
	onShow() {
		this.syncMessageAdConfig();
		this.startRealtime();
		this.loadConversations({ silent: this.conversations.length > 0 });
	},
	onHide() {
		this.closeSwipeAction();
		this.stopRealtime();
	},
	onUnload() {
		this.stopRealtime();
	},
	methods: {
		async syncMessageAdConfig() {
			try {
				await loadAppMode({ force: true });
			} catch (error) {}
			const config = getAppBootstrapConfig();
			const messageAd = config && config.messageAd && typeof config.messageAd === 'object'
				? config.messageAd
				: {};
			this.messageAd = {
				enabled: Boolean(messageAd.enabled),
				primaryText: String(messageAd.primaryText || '把喜欢的对话，再多聊一会').trim()
			};
		},
		setConversationSwipeX(id, value) {
			const conversation = this.conversations.find((item) => item.id === id);
			if (conversation) conversation.swipeX = value;
		},
		handleSwipeStart(id) {
			if (this.deletingConversationId) return;
			if (this.swipedConversationId && this.swipedConversationId !== id) {
				this.setConversationSwipeX(this.swipedConversationId, 0);
				this.swipedConversationId = '';
			}
			this.swipeGestureId = id;
			const conversation = this.conversations.find((item) => item.id === id);
			this.swipeGestureStartX = Number((conversation && conversation.swipeX) || 0);
		},
		handleSwipeChange(event, id) {
			this.swipeLatestPositions[id] = Number(event && event.detail ? event.detail.x : 0);
		},
		handleSwipeEnd(id) {
			if (this.swipeGestureId !== id) return;
			const position = Number(this.swipeLatestPositions[id] || 0);
			const moved = Math.abs(position - this.swipeGestureStartX) > 6;
			const shouldOpen = position <= -this.swipeActionWidthPx / 2;
			this.setConversationSwipeX(id, shouldOpen ? -this.swipeActionWidthPx : 0);
			this.swipedConversationId = shouldOpen ? id : '';
			if (moved) {
				this.suppressRowClickUntil = Date.now() + 350;
			}
			this.swipeGestureId = '';
		},
		closeSwipeAction() {
			if (this.swipedConversationId) this.setConversationSwipeX(this.swipedConversationId, 0);
			this.swipedConversationId = '';
			this.swipeGestureId = '';
		},
		handleListScroll() {
			if (this.swipedConversationId) this.closeSwipeAction();
		},
		handleConversationClick(id) {
			if (Date.now() < this.suppressRowClickUntil) return;
			if (this.swipedConversationId) {
				this.closeSwipeAction();
				return;
			}
			this.goChat(id);
		},
		confirmDeleteConversation(item) {
			if (!item || !item.id || this.deletingConversationId) return;
			uni.showModal({
				title: '删除会话',
				content: `仅从你的聊天列表中删除与“${item.name}”的会话，对方不受影响。`,
				confirmText: '删除',
				confirmColor: '#ef5f6f',
				success: ({ confirm }) => {
					if (confirm) this.deleteConversationItem(item);
				}
			});
		},
		async deleteConversationItem(item) {
			this.deletingConversationId = item.id;
			try {
				await deleteConversation(item.id);
				this.conversations = this.conversations.filter((conversation) => conversation.id !== item.id);
				this.syncTabBadge();
				this.closeSwipeAction();
				uni.showToast({ title: '会话已删除', icon: 'none' });
			} catch (error) {
				showRequestError(error, '删除会话失败');
			} finally {
				this.deletingConversationId = '';
			}
		},
		formatConversationTime(value) {
			if (!value) return '';
			const date = new Date(value);
			if (!date.getTime()) return '';
			const now = new Date();
			const isToday = date.toDateString() === now.toDateString();
			const yesterday = new Date(now);
			yesterday.setDate(now.getDate() - 1);

			if (isToday) {
				return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
			}

			if (date.toDateString() === yesterday.toDateString()) {
				return '昨天';
			}

			const diff = now - date;
			if (diff >= 0 && diff < 7 * 24 * 60 * 60 * 1000) {
				return `星期${'日一二三四五六'[date.getDay()]}`;
			}

			return `${date.getMonth() + 1}-${date.getDate()}`;
		},
		mapConversation(item = {}) {
			const peer = item.peer || {};
			const lastMessage = item.lastMessage || null;
			const preview = this.getConversationPreview(lastMessage);
			return {
				id: item.id,
				name: peer.nickname || peer.stampNo || '想法来客',
				avatar: peer.avatarUrl || DEFAULT_AVATAR_URL,
				preview: lastMessage ? preview : '还没有消息，打个招呼吧',
				time: this.formatConversationTime(item.lastMessageAt || item.updatedAt || item.createdAt),
				unread: Number(item.unreadCount || 0),
				swipeX: 0,
				match: false,
				peerId: peer.id || '',
				isMember: Boolean(peer.isMember),
				online: Boolean(peer.online || isChatUserOnline(peer.id))
			};
		},
		getConversationPreview(message = {}) {
			message = message || {};
			const labelMap = {
				image: '[图片]',
				flash_image: '[闪图]',
				audio: '[语音]',
				gift: '[礼物]',
				membership_gift: '[赠送会员]'
			};
			const text = labelMap[message.messageType] || message.content || '[消息]';
			return message.mine ? `我：${text}` : text;
		},
		normalizeConversationList(result) {
			const source = Array.isArray(result)
				? result
				: Array.isArray(result && result.data)
					? result.data
					: Array.isArray(result && result.items)
						? result.items
						: [];

			return source.reduce((items, conversation) => {
				if (!conversation || !conversation.id) return items;
				try {
					items.push(this.mapConversation(conversation));
				} catch (error) {
					console.error('[messages] 会话转换失败', conversation.id, error);
					const peer = conversation.peer || {};
					items.push({
						id: conversation.id,
						name: peer.nickname || peer.stampNo || '想法来客',
						avatar: peer.avatarUrl || DEFAULT_AVATAR_URL,
						preview: '进入会话查看消息',
						time: '',
						unread: Number(conversation.unreadCount || 0),
						swipeX: 0,
						match: false,
						peerId: peer.id || '',
						isMember: Boolean(peer.isMember),
						online: Boolean(peer.online || isChatUserOnline(peer.id))
					});
				}
				return items;
			}, []);
		},
		async loadConversations(options = {}) {
			if (!options.silent) this.loading = true;
			try {
				const list = await fetchConversations();
				this.conversations = this.normalizeConversationList(list);
				this.syncTabBadge();
			} catch (error) {
				console.error('[messages] 会话列表加载失败', error);
				if (!options.silent) showRequestError(error, '会话加载失败');
			} finally {
				this.loading = false;
				this.refreshing = false;
			}
		},
		refreshConversations() {
			this.refreshing = true;
			this.loadConversations({ silent: true });
		},
		startRealtime() {
			this.stopRealtime();
			this.realtimeUnsubscribe = subscribeChatEvents((event) => {
				if (event.type === 'ready') {
					sendChatSocketEvent('presence.subscribe');
					this.loadConversations({ silent: true });
					return;
				}
				if (event.type === 'presence.snapshot') {
					this.syncOnlineStates();
					return;
				}
				if (event.type === 'presence.changed') {
					const data = event.data || {};
					this.conversations = this.conversations.map((item) => (
						item.peerId === data.userId ? { ...item, online: Boolean(data.online) } : item
					));
					return;
				}
				if (event.type !== 'message.created') return;
				const conversation = event.data && event.data.conversation;
				if (!conversation || !conversation.id) return;

				const mapped = this.mapConversation(conversation);
				this.conversations = [
					mapped,
					...this.conversations.filter((item) => item.id !== mapped.id)
				];
				this.syncTabBadge();
			});
			sendChatSocketEvent('presence.subscribe');
		},
		syncOnlineStates() {
			this.conversations = this.conversations.map((item) => ({
				...item,
				online: isChatUserOnline(item.peerId)
			}));
		},
		stopRealtime() {
			if (!this.realtimeUnsubscribe) return;
			this.realtimeUnsubscribe();
			this.realtimeUnsubscribe = null;
		},
		syncTabBadge() {
			const unreadCount = this.conversations.reduce((total, item) => (
				total + Number(item.unread || 0)
			), 0);
			setMessageTabBadge(unreadCount);
		},
		setTopPadding() {
			try {
				const info = uni.getSystemInfoSync();
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.swipeActionWidthPx = Math.round(120 * rpxToPx);
				if (uni.getMenuButtonBoundingClientRect) {
					const menuButton = uni.getMenuButtonBoundingClientRect();
					if (menuButton && menuButton.top && menuButton.height) {
						this.topPadding = menuButton.top;
						this.heroHeight = menuButton.height;
						return;
					}
				}

				this.topPadding = (info.statusBarHeight || 44) + Math.round(16 * rpxToPx);
				this.heroHeight = Math.round(64 * rpxToPx);
			} catch (error) {
				this.topPadding = 54;
				this.heroHeight = 32;
				this.swipeActionWidthPx = 60;
			}
		},
		async markAllRead() {
			try {
				await Promise.all(this.conversations.filter((item) => item.unread).map((item) => markConversationRead(item.id)));
				this.conversations = this.conversations.map((item) => ({ ...item, unread: 0, dot: false }));
				this.syncTabBadge();
			} catch (error) {
				showRequestError(error, '标记已读失败');
				return;
			}
			uni.showToast({ title: '已全部标记', icon: 'none' });
		},
		async goChat(id) {
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '私信' }))) return;
			uni.navigateTo({ url: `/pages/chat/index?id=${id}` });
		},
		goMembership() {
			uni.navigateTo({ url: '/pages/membership/index' });
		},
		showComingSoon(name) {
			uni.showToast({ title: `${name}即将开放`, icon: 'none' });
		}
	}
};
</script>

<style lang="scss" scoped>
.messages-page {
	height: 100vh;
	min-height: 100vh;
	overflow: hidden;
	background: linear-gradient(180deg, #fbfaff 0%, #ffffff 42%, #fbfcff 100%);
}

.messages-shell {
	position: relative;
	display: flex;
	flex-direction: column;
	height: 100%;
	padding-left: 40rpx;
	padding-right: 0;
	overflow: hidden;
}

.messages-shell::before {
	content: '';
	position: absolute;
	top: 0;
	left: 0;
	right: 0;
	height: 300rpx;
	pointer-events: none;
	background-image:
		linear-gradient(135deg, rgba(236, 229, 255, 0.9) 0%, rgba(255, 247, 252, 0.82) 42%, rgba(232, 250, 244, 0.82) 100%),
		linear-gradient(180deg, rgba(255, 255, 255, 0) 0%, #ffffff 96%);
	border-bottom-left-radius: 46rpx;
	border-bottom-right-radius: 46rpx;
}

.hero-row,
.notice-panel,
.recent-head,
.recent-scroll {
	position: relative;
	z-index: 1;
}

.hero-row {
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 74rpx;
	margin-bottom: 22rpx;
	padding-right: 40rpx;
	box-sizing: border-box;
}

.title-group {
	display: flex;
	align-items: center;
	gap: 0;
	min-width: 0;
}

.subtitle-wrap {
	position: relative;
	padding-bottom: 0;
}

.page-subtitle {
	display: inline-block;
	font-size: 30rpx;
	font-weight: 400;
	color: #686b78;
	line-height: 1;
	animation: subtitleFloatIn 0.82s ease-out both, subtitleGlow 3.8s ease-in-out 0.82s infinite;
}

.subtitle-mark {
	position: absolute;
	left: 176rpx;
	bottom: -18rpx;
	width: 92rpx;
	height: 18rpx;
	border-bottom: 5rpx solid #9a7cff;
	border-radius: 50%;
	transform: rotate(-7deg) scaleX(0);
	transform-origin: left center;
	animation: markDraw 0.68s ease-out 0.32s forwards, markBreathe 3.2s ease-in-out 1.1s infinite;
}

@keyframes subtitleFloatIn {
	from {
		opacity: 0;
		transform: translateY(12rpx);
	}

	to {
		opacity: 1;
		transform: translateY(0);
	}
}

@keyframes subtitleGlow {
	0%,
	100% {
		color: #686b78;
	}

	50% {
		color: #7c68bb;
	}
}

@keyframes markDraw {
	from {
		opacity: 0;
		transform: rotate(-7deg) scaleX(0);
	}

	to {
		opacity: 1;
		transform: rotate(-7deg) scaleX(1);
	}
}

@keyframes markBreathe {
	0%,
	100% {
		opacity: 0.78;
		transform: rotate(-7deg) scaleX(1) translateX(0);
	}

	50% {
		opacity: 1;
		transform: rotate(-4deg) scaleX(1.08) translateX(6rpx);
	}
}

.notice-panel {
	display: grid;
	grid-template-columns: repeat(4, minmax(0, 1fr));
	margin-top: 0;
	padding: 30rpx 16rpx 28rpx;
	border-radius: 32rpx;
	background: linear-gradient(105deg, #f7f2ff 0%, #ffffff 48%, #effbf6 100%);
	box-shadow: none;
}

.notice-item {
	position: relative;
	display: flex;
	flex-direction: column;
	align-items: center;
	min-width: 0;
}

.notice-icon {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 80rpx;
	height: 80rpx;
	margin-bottom: 22rpx;
}

.notice-icon.bubble { color: #9a72ff; }
.notice-icon.heart { color: #ff6ea4; }
.notice-icon.person { color: #4e9af8; }
.notice-icon.bell { color: #5bd995; }

.bubble-shape {
	width: 68rpx;
	height: 58rpx;
	border-radius: 28rpx 28rpx 24rpx 24rpx;
	background: currentColor;
}

.bubble-shape::after {
	content: '';
	position: absolute;
	right: 14rpx;
	bottom: 10rpx;
	width: 18rpx;
	height: 18rpx;
	border-radius: 0 0 18rpx 0;
	background: currentColor;
	transform: rotate(38deg);
}

.bubble-shape::before {
	content: '';
	position: absolute;
	top: 30rpx;
	left: 26rpx;
	width: 8rpx;
	height: 16rpx;
	border-radius: 999rpx;
	background: #ffffff;
	box-shadow: 22rpx 0 0 #ffffff;
}

.heart-shape {
	position: relative;
	width: 56rpx;
	height: 52rpx;
	background: currentColor;
	border-radius: 32rpx 32rpx 12rpx 12rpx;
	transform: rotate(45deg);
}

.heart-shape::before,
.heart-shape::after {
	content: '';
	position: absolute;
	width: 56rpx;
	height: 52rpx;
	border-radius: 50%;
	background: currentColor;
}

.heart-shape::before { left: -22rpx; top: 0; }
.heart-shape::after { left: 0; top: -22rpx; }

.person-shape {
	position: relative;
	width: 64rpx;
	height: 56rpx;
	border-radius: 50% 50% 28rpx 28rpx;
	background: currentColor;
}

.person-shape::before {
	content: '';
	position: absolute;
	left: 18rpx;
	top: -16rpx;
	width: 30rpx;
	height: 30rpx;
	border-radius: 50%;
	background: currentColor;
}

.bell-shape {
	position: relative;
	width: 58rpx;
	height: 60rpx;
	border-radius: 30rpx 30rpx 18rpx 18rpx;
	background: currentColor;
}

.bell-shape::before,
.bell-shape::after {
	content: '';
	position: absolute;
	left: 50%;
	transform: translateX(-50%);
	background: currentColor;
}

.bell-shape::before {
	top: -8rpx;
	width: 18rpx;
	height: 18rpx;
	border-radius: 50%;
}

.bell-shape::after {
	bottom: -10rpx;
	width: 22rpx;
	height: 12rpx;
	border-radius: 0 0 999rpx 999rpx;
}

.notice-badge {
	position: absolute;
	top: -4rpx;
	right: 34rpx;
	display: flex;
	align-items: center;
	justify-content: center;
	min-width: 34rpx;
	height: 34rpx;
	padding: 0 8rpx;
	border-radius: 999rpx;
	background: #ff5763;
	border: 4rpx solid #ffffff;
	color: #ffffff;
	font-size: 20rpx;
	font-weight: 400;
	line-height: 34rpx;
}

.notice-label {
	font-size: 26rpx;
	font-weight: 400;
	color: #20222d;
	line-height: 1.2;
}

.recent-head {
	display: flex;
